"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useId, useState } from "react";

import { cn } from "@/lib/utils";

/** Where one step is. A failed step should carry a `reason`. */
export type AgentStepStatus = "waiting" | "running" | "done" | "failed";

/** One step an agent takes. Name real work only. */
export interface AgentStep {
  id: string;
  label: string;
  status: AgentStepStatus;
  /** Why a failed step failed, in a few plain words. */
  reason?: string;
}

/** Props for the step list. Pass `open` to control it, or `defaultOpen` to let it hold its own state. */
export type AgentStepsProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  steps: AgentStep[];
  /** Seconds since the run began. The caller owns the clock, so a stopped run stops counting. */
  elapsedSeconds?: number;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Adds "Try again" to a failed step. Without it, offer the way forward beside the list. */
  onRetry?: (step: AgentStep) => void;
  /** Seconds after which a running list says it is taking longer than usual. */
  slowAfter?: number;
};

const EASE_OUT = [0.165, 0.84, 0.44, 1] as const;
const COLLAPSE: Transition = { duration: 0.25, ease: EASE_OUT };
const SWAP: Transition = { duration: 0.2, ease: EASE_OUT };
// Rotation that never stops has no start to ease out of.
const SPIN: Transition = { duration: 0.8, ease: "linear", repeat: Infinity };
const FADE: Transition = { duration: 0.15 };

const STATUS_WORD = { waiting: "Waiting", running: "Running", done: "Done", failed: "Failed" } satisfies Record<AgentStepStatus, string>;

function StatusGlyph({ status, still }: { status: AgentStepStatus; still: boolean }) {
  if (status === "running") {
    return (
      <motion.svg
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        aria-hidden="true"
        animate={still ? { rotate: 0 } : { rotate: 360 }}
        transition={still ? FADE : SPIN}
        className="size-4 text-foreground"
      >
        <circle cx="8" cy="8" r="6" opacity="0.25" />
        <path d="M14 8a6 6 0 0 0-6-6" strokeLinecap="round" />
      </motion.svg>
    );
  }
  if (status === "done") {
    return (
      <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4 text-foreground">
        <path d="M8 1a7 7 0 1 1 0 14A7 7 0 0 1 8 1Zm3.2 4.7a.75.75 0 0 0-1.05.1L7.2 9.3 5.8 7.9a.75.75 0 1 0-1.06 1.06l2 2a.75.75 0 0 0 1.11-.05l3.45-4.15a.75.75 0 0 0-.1-1.06Z" />
      </svg>
    );
  }
  if (status === "failed") {
    return (
      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true" className="size-4 text-destructive">
        <path d="m4.5 4.5 7 7m0-7-7 7" strokeLinecap="round" />
      </svg>
    );
  }
  return <span aria-hidden="true" className="size-1.5 rounded-full bg-muted-foreground/60" />;
}

/**
 * A collapsible list of the steps an agent is taking. The running step has a
 * spinner, finished steps a check, waiting steps a dot, and a failed step a
 * cross with its reason. The header shows the current step and the elapsed
 * seconds, and collapses the list.
 */
export function AgentSteps({
  steps,
  elapsedSeconds,
  open,
  defaultOpen = true,
  onOpenChange,
  onRetry,
  slowAfter = 10,
  className,
  ...divProps
}: AgentStepsProps) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const isOpen = open ?? ownOpen;
  const listId = useId();
  const reduceMotion = useReducedMotion();

  // The header names the step that most needs attention: a failure, then the running one.
  const failed = steps.find((step) => step.status === "failed");
  const running = steps.find((step) => step.status === "running");
  const finished = steps.length > 0 && steps.every((step) => step.status === "done");
  const current = failed ?? running;
  const headline = current ? current.label : finished ? "All steps done" : (steps[0]?.label ?? "No steps yet");
  const headStatus: AgentStepStatus = failed ? "failed" : running ? "running" : finished ? "done" : "waiting";
  const slow = Boolean(running) && !failed && elapsedSeconds !== undefined && elapsedSeconds >= slowAfter;

  const toggle = () => {
    if (open === undefined) setOwnOpen(!isOpen);
    onOpenChange?.(!isOpen);
  };

  return (
    <div {...divProps} className={cn("w-full rounded-xl border border-border bg-card text-sm text-foreground", className)}>
      <button
        type="button"
        aria-expanded={isOpen}
        aria-controls={listId}
        onClick={toggle}
        className={cn(
          "flex min-h-11 w-full cursor-pointer touch-manipulation items-center gap-2.5 rounded-xl px-3 text-left outline-none",
          // Inset, so the ring sits inside the card's own border instead of on top of it.
          "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
        )}
      >
        <span className="grid size-4 shrink-0 place-items-center">
          <StatusGlyph status={headStatus} still={Boolean(reduceMotion)} />
        </span>
        <span className="min-w-0 flex-1 truncate font-medium">
          {failed && <span className="sr-only">Failed: </span>}
          {headline}
        </span>
        {elapsedSeconds !== undefined && (
          <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
            {Math.max(0, Math.floor(elapsedSeconds))}s<span className="sr-only"> elapsed</span>
          </span>
        )}
        <motion.svg
          viewBox="0 0 16 16"
          fill="currentColor"
          aria-hidden="true"
          initial={false}
          animate={{ rotate: isOpen ? 180 : 0 }}
          transition={reduceMotion ? { duration: 0 } : SWAP}
          className="size-4 shrink-0 text-muted-foreground"
        >
          <path d="M3.3 5.8a1 1 0 0 1 1.4-.1L8 8.7l3.3-3a1 1 0 1 1 1.4 1.5l-4 3.6a1 1 0 0 1-1.4 0l-4-3.6a1 1 0 0 1 0-1.4Z" />
        </motion.svg>
      </button>
      <motion.div
        id={listId}
        initial={false}
        animate={{ height: isOpen ? "auto" : 0, opacity: isOpen ? 1 : 0 }}
        transition={reduceMotion ? FADE : COLLAPSE}
        // A closed list stays mounted for the height change, so it must leave the Tab order and the reading order.
        inert={!isOpen}
        className="overflow-hidden"
      >
        <ol className="flex flex-col gap-2.5 border-t border-border px-3 py-3">
          {steps.map((step) => (
            <li key={step.id} data-status={step.status} className="flex items-start gap-2.5">
              <motion.span
                // A changed status is a new element, so the glyph fades in when the step moves on.
                key={step.status}
                initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.6 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={reduceMotion ? FADE : SWAP}
                className="grid h-5 w-4 shrink-0 place-items-center"
              >
                <StatusGlyph status={step.status} still={Boolean(reduceMotion)} />
              </motion.span>
              <span className="min-w-0 flex-1">
                <span className={cn("block leading-5", step.status === "waiting" && "text-muted-foreground")}>
                  <span className="sr-only">{STATUS_WORD[step.status]}: </span>
                  {step.label}
                </span>
                {step.status === "failed" && (
                  <span className="flex flex-wrap items-center gap-x-2 text-xs leading-5 text-destructive">
                    <span>{step.reason ?? "This step did not finish."}</span>
                    {onRetry && (
                      <button
                        type="button"
                        onClick={() => onRetry(step)}
                        className="relative cursor-pointer rounded-sm font-medium text-foreground outline-none before:absolute before:-inset-x-2 before:-inset-y-3 hover:text-foreground/80 focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        Try again
                      </button>
                    )}
                  </span>
                )}
              </span>
            </li>
          ))}
        </ol>
        {slow && <p className="px-3 pb-3 text-xs text-muted-foreground">This is taking longer than usual.</p>}
      </motion.div>
      {/* Announces a step change once. The seconds stay out, or they would be read every second. */}
      <span role="status" className="sr-only">
        {failed ? `Failed: ${failed.label}. ${failed.reason ?? ""}` : slow ? `${headline}. This is taking longer than usual.` : headline}
      </span>
    </div>
  );
}
